public List<List<Integer>> kSum(int[] nums, long target, int k) {
    Arrays.sort(nums);
    return kSumHelper(nums, 0, target, k);
}

private List<List<Integer>> kSumHelper(int[] nums, int start, long target, int k) {
    List<List<Integer>> res = new ArrayList<>();
    int n = nums.length;
    if (start >= n) return res;
    if (k == 2) {
        int lo = start, hi = n - 1;
        while (lo < hi) {
            long sum = (long) nums[lo] + nums[hi];
            if (sum < target || (lo > start && nums[lo] == nums[lo - 1])) lo++;
            else if (sum > target || (hi < n - 1 && nums[hi] == nums[hi + 1])) hi--;
            else res.add(new ArrayList<>(Arrays.asList(nums[lo++], nums[hi--])));
        }
        return res;
    }
    for (int i = start; i < n; i++) {
        if (i > start && nums[i] == nums[i - 1]) continue;
        for (List<Integer> sub : kSumHelper(nums, i + 1, target - nums[i], k - 1)) {
            List<Integer> combo = new ArrayList<>();
            combo.add(nums[i]);
            combo.addAll(sub);
            res.add(combo);
        }
    }
    return res;
}

public int trap(int[] height) {
    int l = 0, r = height.length - 1;
    int leftMax = 0, rightMax = 0, res = 0;
    while (l < r) {
        if (height[l] < height[r]) {
            leftMax = Math.max(leftMax, height[l]);
            res += leftMax - height[l];
            l++;
        } else {
            rightMax = Math.max(rightMax, height[r]);
            res += rightMax - height[r];
            r--;
        }
    }
    return res;
}

public int maxArea(int[] height) {
    int l = 0, r = height.length - 1, res = 0;
    while (l < r) {
        res = Math.max(res, Math.min(height[l], height[r]) * (r - l));
        if (height[l] < height[r]) l++;
        else r--;
    }
    return res;
}

public void sortColors(int[] nums) {
    int low = 0, mid = 0, high = nums.length - 1;
    while (mid <= high) {
        if (nums[mid] == 0) {
            int t = nums[low]; nums[low] = nums[mid]; nums[mid] = t;
            low++; mid++;
        } else if (nums[mid] == 1) {
            mid++;
        } else {
            int t = nums[mid]; nums[mid] = nums[high]; nums[high] = t;
            high--;
        }
    }
}

public int numSubarrayProductLessThanK(int[] nums, int k) {
    if (k <= 1) return 0;
    int prod = 1, left = 0, res = 0;
    for (int right = 0; right < nums.length; right++) {
        prod *= nums[right];
        while (prod >= k) prod /= nums[left++];
        res += right - left + 1;
    }
    return res;
}

public int numRescueBoats(int[] people, int limit) {
    Arrays.sort(people);
    int i = 0, j = people.length - 1, boats = 0;
    while (i <= j) {
        if (people[i] + people[j] <= limit) i++;
        j--;
        boats++;
    }
    return boats;
}

public int threeSumSmaller(int[] nums, int target) {
    Arrays.sort(nums);
    int count = 0, n = nums.length;
    for (int i = 0; i < n - 2; i++) {
        int lo = i + 1, hi = n - 1;
        while (lo < hi) {
            if (nums[i] + nums[lo] + nums[hi] < target) {
                count += hi - lo;
                lo++;
            } else {
                hi--;
            }
        }
    }
    return count;
}

public int countPairs(int[] nums, int target) {
    Arrays.sort(nums);
    int lo = 0, hi = nums.length - 1, count = 0;
    while (lo < hi) {
        if (nums[lo] + nums[hi] < target) {
            count += hi - lo;
            lo++;
        } else {
            hi--;
        }
    }
    return count;
}

public int trapRainWater(int[][] heightMap) {
    if (heightMap == null || heightMap.length < 3 || heightMap[0].length < 3) return 0;
    int m = heightMap.length, n = heightMap[0].length;
    boolean[][] visited = new boolean[m][n];
    PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[2] - b[2]);
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (i == 0 || i == m - 1 || j == 0 || j == n - 1) {
                pq.offer(new int[]{i, j, heightMap[i][j]});
                visited[i][j] = true;
            }
        }
    }
    int[] dirs = {-1, 0, 1, 0, -1};
    int water = 0;
    while (!pq.isEmpty()) {
        int[] cell = pq.poll();
        int level = cell[2];
        for (int d = 0; d < 4; d++) {
            int ni = cell[0] + dirs[d], nj = cell[1] + dirs[d + 1];
            if (ni < 0 || ni >= m || nj < 0 || nj >= n || visited[ni][nj]) continue;
            visited[ni][nj] = true;
            water += Math.max(0, level - heightMap[ni][nj]);
            pq.offer(new int[]{ni, nj, Math.max(level, heightMap[ni][nj])});
        }
    }
    return water;
}
